from dataclasses import dataclass

import pytest


@dataclass
class Rect:
    w: int
    h: int


@dataclass
class Square:
    side: int


@dataclass
class Tri:
    b: int
    h: int


Shape = Rect | Square | Tri


def area(s: Shape) -> int:
    """Area of the shape, rounded down to an integer.

    Rect: w * h. Square: side * side. Tri: b * h / 2, floored.
    """
    if isinstance(s, Rect):
        return s.w * s.h
    if isinstance(s, Square):
        return s.side * s.side
    return s.b * s.h // 2


def test_rect() -> None:
    assert area(Rect(3, 4)) == 12


def test_rect_zero_width() -> None:
    assert area(Rect(0, 7)) == 0


def test_square() -> None:
    assert area(Square(5)) == 25


def test_tri_even_product() -> None:
    assert area(Tri(4, 6)) == 12


def test_tri_odd_product_rounds_down() -> None:
    assert area(Tri(3, 5)) == 7


def test_tri_zero_base() -> None:
    assert area(Tri(0, 9)) == 0


@pytest.mark.parametrize(
    ("shape", "expected"),
    [
        (Rect(2, 2), 4),
        (Square(1), 1),
        (Tri(1, 1), 0),
        (Tri(7, 3), 10),
    ],
)
def test_area_parametrized(shape: Shape, expected: int) -> None:
    assert area(shape) == expected
